package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var DateRecVar DateRec

var dateFileLines []string
var dateFileIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncVal(v int64, digits int) int64 {
	m := pow10(digits)
	if m == 0 {
		return v
	}
	r := v % m
	if r < 0 {
		r += m
	}
	return r
}

func fmtNum(v int64, width int) string {
	v = truncVal(v, width)
	if v < 0 {
		v = 0
	}
	s := strconv.FormatInt(v, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func fmtX(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func parseNum(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	t = strings.TrimSpace(t)
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// extract digits only
		d := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				d += string(c)
			}
		}
		if d == "" {
			return 0
		}
		n, _ = strconv.ParseInt(d, 10, 64)
	}
	return n
}

func parseDateRec(line string) DateRec {
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		line = line[:12]
	}
	var r DateRec
	r.DtId = line[0:4]
	r.DtYyyy = truncVal(parseNum(line[4:8]), 4)
	r.DtMm = truncVal(parseNum(line[8:10]), 2)
	r.DtDd = truncVal(parseNum(line[10:12]), 2)
	return r
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		dateFileLines = []string{}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// Scanner strips \n and \r\n? It strips \n and optional \r? Actually ScanLines strips \r\n -> \r removed. Good.
			dateFileLines = append(dateFileLines, line)
		}
		f.Close()
	}
	dateFileIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE DATE-FILE (nothing)
	fmt.Println("VALID: "+fmtNum(WsValid, 2)+" BAD MONTH: "+fmtNum(WsBadMonth, 2)+" BAD DAY: "+fmtNum(WsBadDay, 2))
}

func READPARA() {
	if dateFileIdx >= len(dateFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := dateFileLines[dateFileIdx]
	dateFileIdx++
	DateRecVar = parseDateRec(line)
}

func PROCESSPARA() {
	LEAPPARA()
	dtMm := DateRecVar.DtMm
	if dtMm < 1 || dtMm > 12 {
		WsBadMonth = truncVal(WsBadMonth+1, 2)
		fmt.Println(fmtX(DateRecVar.DtId, 4)+" BAD MONTH "+fmtNum(DateRecVar.DtMm, 2))
	} else {
		DAYSPARA()
		if DateRecVar.DtDd < 1 || DateRecVar.DtDd > WsMaxDay {
			WsBadDay = truncVal(WsBadDay+1, 2)
			fmt.Println(fmtX(DateRecVar.DtId, 4)+" BAD DAY "+fmtNum(DateRecVar.DtDd, 2)+" MAX "+fmtNum(WsMaxDay, 2))
		} else {
			WsValid = truncVal(WsValid+1, 2)
			fmt.Println(fmtX(DateRecVar.DtId, 4)+" VALID "+fmtNum(DateRecVar.DtYyyy, 4)+"-"+fmtNum(DateRecVar.DtMm, 2)+"-"+fmtNum(DateRecVar.DtDd, 2))
		}
	}
	READPARA()
}

func LEAPPARA() {
	yyyy := DateRecVar.DtYyyy
	q4 := yyyy / 4
	r4 := yyyy - q4*4
	WsQ = truncVal(q4, 4)
	WsR4 = truncVal(r4, 3)
	q100 := yyyy / 100
	r100 := yyyy - q100*100
	WsQ = truncVal(q100, 4)
	WsR100 = truncVal(r100, 3)
	q400 := yyyy / 400
	r400 := yyyy - q400*400
	WsQ = truncVal(q400, 4)
	WsR400 = truncVal(r400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch DateRecVar.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	MAINPARA()
}
